def longest_palindrome(s: str) -> str:
    if len(s) < 2:
        return s

    start = 0
    max_len = 1

    def expand(left: int, right: int) -> None:
        nonlocal start, max_len
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        length = right - left - 1
        if length > max_len:
            max_len = length
            start = left + 1

    for i in range(len(s)):
        expand(i, i)      # 奇数长度回文
        expand(i, i + 1)  # 偶数长度回文

    return s[start:start + max_len]
